package com.ninho.social;
import com.ninho.shared.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class SocialService {
 private final JdbcTemplate db;public SocialService(JdbcTemplate db){this.db=db;}
 private Map<String,Object> friendship(UUID id,UUID user,boolean lock){var list=db.queryForList("SELECT * FROM friendship WHERE id=? AND (host_id=? OR guest_id=?) AND status<>'removed'"+(lock?" FOR UPDATE":""),id,user,user);if(list.isEmpty())throw DomainException.missing();return list.getFirst();}
 private UUID peer(Map<String,Object> f,UUID user){return user.equals(f.get("host_id"))?(UUID)f.get("guest_id"):(UUID)f.get("host_id");}
 private boolean blocked(UUID a,UUID b){return b!=null&&db.queryForObject("SELECT COUNT(*) FROM friend_block WHERE (owner_id=? AND peer_id=?) OR (owner_id=? AND peer_id=?)",Integer.class,a,b,b,a)>0;}
 private Map<String,Object> view(Map<String,Object> f,UUID user){var dto=new LinkedHashMap<String,Object>();boolean host=user.equals(f.get("host_id"));UUID peer=peer(f,user);dto.put("id",f.get("id"));dto.put("role",host?"host":"guest");dto.put("status",f.get("status"));dto.put("name",Objects.toString(host?f.get("guest_name"):f.get("host_name"),"Seu convite"));dto.put("available",!blocked(user,peer));dto.put("blockedByMe",peer!=null&&db.queryForObject("SELECT COUNT(*) FROM friend_block WHERE owner_id=? AND peer_id=?",Integer.class,user,peer)>0);return dto;}
 public Object list(UUID user){return Map.of("friends",db.queryForList("SELECT * FROM friendship WHERE (host_id=? OR guest_id=?) AND status IN ('pending','accepted') ORDER BY created_at DESC",user,user).stream().map(f->view(f,user)).toList());}
 @Transactional public Object create(UUID id,UUID user,String name){var previous=db.queryForList("SELECT * FROM friendship WHERE id=?",id);if(!previous.isEmpty()){if(!user.equals(previous.getFirst().get("host_id")))throw DomainException.missing();return view(previous.getFirst(),user);}long now=System.currentTimeMillis();db.update("INSERT INTO friendship(id,host_id,host_name,status,created_at,expires_at) VALUES(?,?,?,'pending',?,?)",id,user,name,now,now+86400000);return view(friendship(id,user,false),user);}
 public Object preview(UUID id,UUID user){var list=db.queryForList("SELECT * FROM friendship WHERE id=? AND status IN ('pending','accepted')",id);if(list.isEmpty())throw DomainException.missing();var f=list.getFirst();if(f.get("status").equals("pending")&&(long)f.get("expires_at")<System.currentTimeMillis())throw new DomainException(410,"INVITE_EXPIRED","Esse convite venceu. Peça um novo convite.");if(blocked(user,(UUID)f.get("host_id")))throw new DomainException(403,"BLOCKED","Essa conversa não está disponível.");return Map.of("id",id,"name",f.get("host_name"),"alreadyJoined",user.equals(f.get("guest_id"))||user.equals(f.get("host_id")));}
 @Transactional public Object accept(UUID id,UUID user,String name){var list=db.queryForList("SELECT * FROM friendship WHERE id=? AND status IN ('pending','accepted') FOR UPDATE",id);if(list.isEmpty())throw DomainException.missing();var f=list.getFirst();if(user.equals(f.get("host_id"))||user.equals(f.get("guest_id")))return view(f,user);if(f.get("guest_id")!=null)throw DomainException.conflict("Esse convite já encontrou sua companhia.");if((long)f.get("expires_at")<System.currentTimeMillis())throw new DomainException(410,"INVITE_EXPIRED","Esse convite venceu. Peça um novo convite.");if(blocked(user,(UUID)f.get("host_id")))throw new DomainException(403,"BLOCKED","Essa conversa não está disponível.");db.update("UPDATE friendship SET guest_id=?,guest_name=?,status='accepted' WHERE id=? AND guest_id IS NULL",user,name,id);return view(friendship(id,user,false),user);}
 private Map<String,Object> conversation(UUID id,UUID user,boolean lock){var f=friendship(id,user,lock);if(!f.get("status").equals("accepted"))throw DomainException.conflict("A outra pessoa ainda não entrou.");if(blocked(user,peer(f,user)))throw new DomainException(403,"BLOCKED","Essa conversa não está disponível.");return f;}
 @Transactional public Object send(UUID id,UUID user,String messageId,String iv,String ciphertext){var f=conversation(id,user,true);String sender=user.equals(f.get("host_id"))?"host":"guest";if(db.queryForObject("SELECT COUNT(*) FROM friend_message WHERE friendship_id=? AND message_id=?",Integer.class,id,messageId)==0)db.update("INSERT INTO friend_message(friendship_id,message_id,sender,iv,ciphertext,created_at) VALUES(?,?,?,?,?,?)",id,messageId,sender,iv,ciphertext,System.currentTimeMillis());return Map.of("received",true);}
 public Object messages(UUID id,UUID user,long after){conversation(id,user,false);var messages=db.query("SELECT * FROM friend_message WHERE friendship_id=? AND seq>? ORDER BY seq LIMIT 100",(r,n)->Map.of("seq",r.getLong("seq"),"sender",r.getString("sender"),"envelope",Map.of("v",1,"id",r.getString("message_id"),"iv",r.getString("iv"),"ciphertext",r.getString("ciphertext"))),id,after);return Map.of("messages",messages);}
 @Transactional public Object block(UUID id,UUID user,boolean block){var f=friendship(id,user,true);var peer=peer(f,user);if(peer==null)throw DomainException.conflict("Esse convite ainda não tem outra pessoa.");if(block&&db.queryForObject("SELECT COUNT(*) FROM friend_block WHERE owner_id=? AND peer_id=?",Integer.class,user,peer)==0)db.update("INSERT INTO friend_block(owner_id,peer_id,friendship_id,created_at) VALUES(?,?,?,?)",user,peer,id,System.currentTimeMillis());if(!block)db.update("DELETE FROM friend_block WHERE owner_id=? AND peer_id=?",user,peer);return Map.of("blocked",block);}
 @Transactional public Object remove(UUID id,UUID user){friendship(id,user,true);db.update("UPDATE friendship SET status='removed' WHERE id=?",id);db.update("DELETE FROM friend_message WHERE friendship_id=?",id);return Map.of("removed",true);}
 @Transactional public Object decline(UUID id,UUID user){preview(id,user);if(db.queryForObject("SELECT COUNT(*) FROM invite_decline WHERE friendship_id=? AND user_id=?",Integer.class,id,user)==0)db.update("INSERT INTO invite_decline(friendship_id,user_id,created_at) VALUES(?,?,?)",id,user,System.currentTimeMillis());return Map.of("declined",true);}
}